def analyze_text_file(filename):
    try:
        with open(filename, 'r') as f:
            lines = words = chars_total = chars_no_space = 0
            for line in f:
                lines += 1
                chars_total += len(line)
                chars_no_space += len(line.replace(' ', '').replace('\n', '').replace('\t', ''))
                words += len(line.split())
            avg_word_len = chars_no_space / words if words else 0
            return {
                'lines': lines,
                'words': words,
                'chars_total': chars_total,
                'chars_no_space': chars_no_space,
                'avg_word_length': round(avg_word_len, 2)
            }
    except FileNotFoundError:
        return {'error': 'File not found'}
```
Good answer uses iteration (memory-safe), accumulates counts in one pass, handles division by zero, and catches `FileNotFoundError`. Poor answer uses `read()` or `readlines()` (memory risk), ignores exceptions, or computes `avg_word_length` incorrectly using `chars_total`.
